import{_ as t,o as e,c as a,Q as d}from"./chunks/framework.48927342.js";const g=JSON.parse('{"title":"Chef Job Application","description":"","frontmatter":{},"headers":[],"relativePath":"en/more/maltese/practice/emails/07-chef-job-application.md","filePath":"en/more/maltese/practice/emails/07-chef-job-application.md"}'),r={name:"en/more/maltese/practice/emails/07-chef-job-application.md"},o=d('<h1 id="chef-job-application" tabindex="-1">Chef Job Application <a class="header-anchor" href="#chef-job-application" aria-label="Permalink to &quot;Chef Job Application&quot;">​</a></h1><p><strong>Scenario:</strong> The applicant writes to the restaurant manager to apply for the position of chef.</p><h2 id="email-header" tabindex="-1">Email Header <a class="header-anchor" href="#email-header" aria-label="Permalink to &quot;Email Header&quot;">​</a></h2><p><strong>Lil (To):</strong> <a href="mailto:info@restorant.com" target="_blank" rel="noreferrer">info@restorant.com</a><strong>Mingħand (From):</strong> [isem]@email.com <strong>Data (Date):</strong> 15 ta&#39; Ottubru 2026 <strong>Suġġett (Subject):</strong> Applikazzjoni ta&#39; xogħol ta&#39; kok</p><h2 id="full-email" tabindex="-1">Full Email <a class="header-anchor" href="#full-email" aria-label="Permalink to &quot;Full Email&quot;">​</a></h2><blockquote><p><strong>Lil:</strong> <a href="mailto:info@restorant.com" target="_blank" rel="noreferrer">info@restorant.com</a><strong>Mingħand:</strong> [isem]@email.com <strong>Data:</strong> 15 ta&#39; Ottubru 2026 <strong>Suġġett:</strong> Applikazzjoni ta&#39; xogħol ta&#39; kok</p><p>Għażiż Sinjur / Sinjura,</p><p>Qed nikteb biex napplika għall-impjieg ta&#39; kok fir-ristorant tagħkom.</p><p>Għandi ħames snin esperjenza fil-kċina.</p><p>Naf insajjar platti tradizzjonali Maltin u Mediterranji.</p><p>Jien bniedem li jaħdem iebes u jimpurtani mill-kwalità tal-ikel.</p><p>Naħdem ukoll tajjeb ma&#39; tim.</p><p>Nixtieq niltaqgħa miegħkom għal intervista meta jkun konvenjenti.</p><p>Grazzi ħafna talli qiesu l-applikazzjoni tiegħi.</p><p>Nispera li nisma&#39; mingħandkom dalwaqt.</p><p>Tislijiet, [Ismek]</p></blockquote><h2 id="sentence-by-sentence-translation-and-word-notes" tabindex="-1">Sentence-by-Sentence Translation and Word Notes <a class="header-anchor" href="#sentence-by-sentence-translation-and-word-notes" aria-label="Permalink to &quot;Sentence-by-Sentence Translation and Word Notes&quot;">​</a></h2><p><strong>Malti:</strong> Lil: <a href="mailto:info@restorant.com" target="_blank" rel="noreferrer">info@restorant.com</a></p><p><strong>Translation:</strong> To: <a href="mailto:info@restorant.com" target="_blank" rel="noreferrer">info@restorant.com</a></p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Lil</td><td>to; recipient</td><td>Maltese label for the email &quot;To&quot; field</td></tr><tr><td><a href="mailto:info@restorant.com" target="_blank" rel="noreferrer">info@restorant.com</a></td><td>email address</td><td>The restaurant&#39;s recruitment email (example)</td></tr></tbody></table><p><strong>Malti:</strong> Mingħand: [isem]@email.com</p><p><strong>Translation:</strong> From: [your name]@email.com</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Mingħand</td><td>from; sender</td><td>Maltese label for the email &quot;From&quot; field; literally &quot;from ...&quot;</td></tr><tr><td>[isem]@email.com</td><td>email address</td><td>Placeholder for your email; replace with your real one</td></tr></tbody></table><p><strong>Malti:</strong> Data: 15 ta&#39; Ottubru 2026</p><p><strong>Translation:</strong> Date: 15 October 2026</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Data</td><td>date</td><td>Email &quot;Date&quot; field; Maltese date format is &quot;day ta&#39; month year&quot;</td></tr><tr><td>15</td><td>fifteen</td><td>Day in the date</td></tr><tr><td>ta&#39;</td><td>of</td><td>Links the day and the month</td></tr><tr><td>Ottubru</td><td>October</td><td>Month name</td></tr></tbody></table><p><strong>Malti:</strong> Suġġett: Applikazzjoni ta&#39; xogħol ta&#39; kok</p><p><strong>Translation:</strong> Subject: Application for the Position of Chef</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Suġġett</td><td>subject</td><td>Email &quot;Subject&quot; field</td></tr><tr><td>Applikazzjoni</td><td>application</td><td>Feminine loanword from application</td></tr><tr><td>ta&#39;</td><td>of</td><td>Possession linker</td></tr><tr><td>xogħol</td><td>work; job</td><td>Masculine noun</td></tr><tr><td>ta&#39;</td><td>of</td><td>Possession linker</td></tr><tr><td>kok</td><td>chef; cook</td><td>Masculine loanword from cook</td></tr></tbody></table><p><strong>Malti:</strong> Għażiż Sinjur / Sinjura,</p><p><strong>Translation:</strong> Dear Sir / Madam,</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Għażiż</td><td>dear</td><td>Masculine singular form</td></tr><tr><td>Sinjur</td><td>sir; Mr.</td><td>Masculine noun</td></tr><tr><td>/</td><td>or</td><td>Indicates a choice between two</td></tr><tr><td>Sinjura</td><td>madam; Mrs.</td><td>Feminine noun</td></tr></tbody></table><h3 id="_1" tabindex="-1">1. <a class="header-anchor" href="#_1" aria-label="Permalink to &quot;1.&quot;">​</a></h3><p><strong>Malti:</strong> Qed nikteb biex napplika għall-impjieg ta&#39; kok fir-ristorant tagħkom.</p><p><strong>Translation:</strong> I am writing to apply for the position of chef in your restaurant.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Qed</td><td>am (progressive marker)</td><td>Used with a verb to indicate an ongoing action</td></tr><tr><td>nikteb</td><td>I write</td><td>First-person singular present</td></tr><tr><td>biex</td><td>in order to</td><td>Introduces a purpose clause</td></tr><tr><td>napplika</td><td>I apply</td><td>First-person singular form, loanword from apply</td></tr><tr><td>għall-impjieg</td><td>for the job</td><td>Contracted <code>għal</code> + <code>l-impjieg</code></td></tr><tr><td>ta&#39;</td><td>of</td><td>Possession/category linker</td></tr><tr><td>kok</td><td>chef; cook</td><td>Masculine loanword from cook</td></tr><tr><td>fir-ristorant</td><td>in the restaurant</td><td>Contracted <code>f&#39;</code> + <code>ir-ristorant</code></td></tr><tr><td>tagħkom</td><td>your (plural)</td><td>Plural possessive pronoun</td></tr></tbody></table><h3 id="_2" tabindex="-1">2. <a class="header-anchor" href="#_2" aria-label="Permalink to &quot;2.&quot;">​</a></h3><p><strong>Malti:</strong> Għandi ħames snin esperjenza fil-kċina.</p><p><strong>Translation:</strong> I have five years of kitchen experience.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Għandi</td><td>I have</td><td>First-person singular form of <code>għand</code></td></tr><tr><td>ħames</td><td>five</td><td>Numeral followed by a plural noun</td></tr><tr><td>snin</td><td>years</td><td>Plural of <code>sena</code></td></tr><tr><td>esperjenza</td><td>experience</td><td>Feminine noun</td></tr><tr><td>fil-kċina</td><td>in the kitchen</td><td>Contracted <code>f&#39;</code> + <code>il-kċina</code></td></tr></tbody></table><h3 id="_3" tabindex="-1">3. <a class="header-anchor" href="#_3" aria-label="Permalink to &quot;3.&quot;">​</a></h3><p><strong>Malti:</strong> Naf insajjar platti tradizzjonali Maltin u Mediterranji.</p><p><strong>Translation:</strong> I can cook traditional Maltese and Mediterranean dishes.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Naf</td><td>I know; I can</td><td>First-person singular form</td></tr><tr><td>insajjar</td><td>I cook</td><td>First-person singular present</td></tr><tr><td>platti</td><td>dishes</td><td>Plural of <code>platt</code></td></tr><tr><td>tradizzjonali</td><td>traditional</td><td>Adjective</td></tr><tr><td>Maltin</td><td>Maltese</td><td>Plural of <code>Malti</code></td></tr><tr><td>u</td><td>and</td><td>Conjunction</td></tr><tr><td>Mediterranji</td><td>Mediterranean</td><td>Plural adjective</td></tr></tbody></table><h3 id="_4" tabindex="-1">4. <a class="header-anchor" href="#_4" aria-label="Permalink to &quot;4.&quot;">​</a></h3><p><strong>Malti:</strong> Jien bniedem li jaħdem iebes u jimpurtani mill-kwalità tal-ikel.</p><p><strong>Translation:</strong> I am a person who works hard and cares about the quality of the food.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Jien</td><td>I</td><td>First-person singular pronoun</td></tr><tr><td>bniedem</td><td>person; human being</td><td>Masculine noun</td></tr><tr><td>li</td><td>who; that</td><td>Relative pronoun</td></tr><tr><td>jaħdem</td><td>he works</td><td>Third-person masculine singular</td></tr><tr><td>iebes</td><td>hard; industrious</td><td>Used as an adverb &quot;hard&quot; here</td></tr><tr><td>u</td><td>and</td><td>Conjunction</td></tr><tr><td>jimpurtani</td><td>I care</td><td><code>jimpurta</code> + <code>-ni</code> &quot;me&quot;; idiomatic expression</td></tr><tr><td>mill-kwalità</td><td>about the quality</td><td>Contracted <code>minn</code> + <code>il-kwalità</code></td></tr><tr><td>tal-ikel</td><td>of the food</td><td>Contracted <code>ta&#39;</code> + <code>l-ikel</code></td></tr></tbody></table><h3 id="_5" tabindex="-1">5. <a class="header-anchor" href="#_5" aria-label="Permalink to &quot;5.&quot;">​</a></h3><p><strong>Malti:</strong> Naħdem ukoll tajjeb ma&#39; tim.</p><p><strong>Translation:</strong> I also work well with a team.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Naħdem</td><td>I work</td><td>First-person singular present</td></tr><tr><td>ukoll</td><td>also; as well</td><td>Adverb</td></tr><tr><td>tajjeb</td><td>well</td><td>Used as an adverb here</td></tr><tr><td>ma&#39;</td><td>with</td><td>Preposition</td></tr><tr><td>tim</td><td>team</td><td>Masculine loanword from team</td></tr></tbody></table><h3 id="_6" tabindex="-1">6. <a class="header-anchor" href="#_6" aria-label="Permalink to &quot;6.&quot;">​</a></h3><p><strong>Malti:</strong> Nixtieq niltaqgħa miegħkom għal intervista meta jkun konvenjenti.</p><p><strong>Translation:</strong> I would like to meet you for an interview whenever it is convenient.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Nixtieq</td><td>I would like; I wish</td><td>Polite expression of a wish</td></tr><tr><td>niltaqgħa</td><td>I meet</td><td>First-person singular form</td></tr><tr><td>miegħkom</td><td>with you (plural)</td><td><code>miegħ</code> &quot;with&quot; + <code>-kom</code> &quot;you&quot;</td></tr><tr><td>għal</td><td>for</td><td>Preposition</td></tr><tr><td>intervista</td><td>interview</td><td>Feminine loanword from interview</td></tr><tr><td>meta</td><td>when</td><td>Conjunction</td></tr><tr><td>jkun</td><td>it will be</td><td>Third-person singular, used with <code>konvenjenti</code></td></tr><tr><td>konvenjenti</td><td>convenient</td><td>Adjective</td></tr></tbody></table><h3 id="_7" tabindex="-1">7. <a class="header-anchor" href="#_7" aria-label="Permalink to &quot;7.&quot;">​</a></h3><p><strong>Malti:</strong> Grazzi ħafna talli qiesu l-applikazzjoni tiegħi.</p><p><strong>Translation:</strong> Thank you very much for considering my application.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Grazzi</td><td>thank you</td><td>Polite phrase</td></tr><tr><td>ħafna</td><td>very; much</td><td>Adverb of degree</td></tr><tr><td>talli</td><td>for (your) ...</td><td>Written expression introducing a reason</td></tr><tr><td>qiesu</td><td>they considered</td><td>Third-person plural past of <code>qies</code> &quot;consider/look at&quot;</td></tr><tr><td>l-applikazzjoni</td><td>the application</td><td>Feminine noun with the definite article</td></tr><tr><td>tiegħi</td><td>my; mine</td><td>Possessive pronoun</td></tr></tbody></table><h3 id="_8" tabindex="-1">8. <a class="header-anchor" href="#_8" aria-label="Permalink to &quot;8.&quot;">​</a></h3><p><strong>Malti:</strong> Nispera li nisma&#39; mingħandkom dalwaqt.</p><p><strong>Translation:</strong> I hope to hear from you soon.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Nispera</td><td>I hope</td><td>First-person singular form</td></tr><tr><td>li</td><td>that; introduces a clause</td><td>Conjunction</td></tr><tr><td>nisma&#39;</td><td>I hear; I receive news</td><td>First-person singular form</td></tr><tr><td>mingħandkom</td><td>from you (plural)</td><td><code>mingħand</code> &quot;from ...&quot; + <code>-kom</code> &quot;you&quot;</td></tr><tr><td>dalwaqt</td><td>soon</td><td>Adverb, from <code>dal-</code> &quot;this&quot; + <code>waqt</code> &quot;moment&quot;</td></tr></tbody></table><p><strong>Malti:</strong> Tislijiet, [Ismek]</p><p><strong>Translation:</strong> Regards, [your name] (formal email closing).</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Tislijiet</td><td>regards; best wishes</td><td>Formal email/letter closing, literally &quot;greetings/regards&quot;</td></tr><tr><td>Ismek</td><td>your name</td><td><code>isem</code> &quot;name&quot; + <code>-ek</code> &quot;your&quot;; replace with your real name</td></tr></tbody></table>',57),n=[o];function i(l,s,h,p,c,m){return e(),a("div",null,n)}const b=t(r,[["render",i]]);export{g as __pageData,b as default};
